`timescale 1ns/1ps
module tb;
  logic [7:0] l8;
  bit [7:0] b8;
  byte by;
  byte unsigned bu;
  shortint si;
  shortint unsigned su;
  int i;
  int unsigned iu;
  longint li;
  longint unsigned lu;
  integer ig;
  bit b1;
  logic l1;
  reg [3:0] r4;
  initial begin
    $display("A1 init l8=%b b8=%b by=%0d si=%0d i=%0d li=%0d ig=%0d b1=%b l1=%b", l8, b8, by, si, i, li, ig, b1, l1);
    l8 = 8'bx1z0_1010; b8 = 8'bx1z0_1010;
    $display("A2 l8=%b b8=%b", l8, b8);
    by = 8'hff; bu = 8'hff;
    $display("A3 by=%0d bu=%0d by=%h bu=%h", by, bu, by, bu);
    si = 16'h8000; su = 16'h8000;
    $display("A4 si=%0d su=%0d", si, su);
    i = 32'hffff_fffe; iu = 32'hffff_fffe;
    $display("A5 i=%0d iu=%0d i=%h", i, iu, i);
    li = 64'h8000_0000_0000_0000; lu = 64'h8000_0000_0000_0000;
    $display("A6 li=%0d lu=%0d", li, lu);
    ig = -5;
    $display("A7 ig=%0d ig=%h ig=%b", ig, ig, ig);
    ig = 'x;
    $display("A8 ig=%0d ig=%h", ig, ig);
    i = 'x;
    $display("A9 i(2state from x)=%0d", i);
    b1 = 1'bz; l1 = 1'bz;
    $display("A10 b1=%b l1=%b", b1, l1);
    $display("A11 bits byte=%0d shortint=%0d int=%0d longint=%0d integer=%0d", $bits(by), $bits(si), $bits(i), $bits(li), $bits(ig));
    by = -1;
    i = by;
    $display("A12 byte->int sext i=%0d %h", i, i);
    bu = 8'hf0;
    i = bu;
    $display("A13 byte unsigned->int i=%0d %h", i, i);
    by = 8'd200;
    $display("A14 by=200 -> %0d", by);
    si = -300; by = si;
    $display("A15 trunc si=-300 -> by=%0d %h", by, by);
    iu = -1;
    li = iu;
    $display("A16 iu=-1 -> li=%0d", li);
    i = -1;
    lu = i;
    $display("A17 i=-1 -> lu=%h", lu);
    r4 = 4'b1x0z;
    b8 = r4;
    $display("A18 r4=%b b8=%b", r4, b8);
    by = -128; by = by - 1;
    $display("A19 wrap by=%0d", by);
    i = 7; ig = 7;
    $display("A20 i/2=%0d -i/2=%0d ig%%3=%0d -ig%%3=%0d", i/2, -i/2, ig%3, (-ig)%3);
    $display("A21 int<0? %0d byte<0? %0d bu<0? %0d", (i - 8) < 0, (by) < 0, (bu) < 0);
    $display("A22 x==x l: %b, bit compare: %b", l8 == l8, b8 == b8);
    $display("A23 sizes %0d %0d %0d", $bits(bu), $bits(su), $bits(lu));
    $display("A24 su=%h lu=%0d", su, lu);
    $finish;
  end
endmodule
